(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth || 800;
  const height = canvas.height = canvas.clientHeight || 600;

  // ---- Game state ----
  // Ship object
  let ship = { x: width / 2, y: height - 60, w: 40, h: 40, speed: 5 };
  // Asteroids with rotation
  let asteroids = [];
  // Fuel canisters
  let fuels = [];
  // Fuel percentage
  let fuel = 100; // percent
  let score = 0;

input.oldString:
// asteroids – gray circles
ctx.fillStyle = '#888';
asteroids.forEach(a => {
  ctx.beginPath();
  ctx.arc(a.x + a.w / 2, a.y + a.h / 2, a.w / 2, 0, Math.PI * 2);
  ctx.fill();
});

input.newString:
// asteroids – rotating gray rocks
asteroids.forEach(a => {
  ctx.save();
  const cx = a.x + a.w / 2;
  const cy = a.y + a.h / 2;
  ctx.translate(cx, cy);
  ctx.rotate(a.rotation);
  // slight colour variation based on size
  const shade = Math.floor(150 + (a.w / 80) * 105);
  ctx.fillStyle = `rgb(${shade},${shade},${shade})`;
  ctx.beginPath();
  ctx.arc(0, 0, a.w / 2, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
});

